/**
 * lib/holo-walk/data.ts — The LOCATIONS catalogue itself.
 *
 * Pure data registry — exempt from the 300-line cap per
 * ARCHITECTURE.md Rule 1 ("Does not apply to generated files,
 * registry indices ..."). Extracted from `lib/holo-walk/locations.ts`
 * (formerly 2039 lines) so the types and query helpers can live in
 * their own files; consumers continue to import from `locations.ts`
 * which re-exports from here.
 *
 * Adding a new trail location: append a new entry below following
 * the SculptureLocation shape. The deploy capability documentation
 * + the operator notes near the top of this file explain how to
 * populate `splat` when a Gaussian Splat capture exists for the spot.
 */

import type { SculptureLocation } from "./types";

// =============================================================================
// OPERATOR NOTE — populating splat URLs
// =============================================================================
//
// Every entry below has GPS, heading, and an `attractor` sculpture spec.
// None currently has a `splat` field populated, which means the AR view
// renders the algorithmic attractor as the headline (the detail page
// surfaces this in plain text to visitors so it's not a surprise).
//
// To attach a trained splat to a location, add a `splat: SplatAsset`
// field to its record. Three populate paths, in order of recommendation:
//
//   1. **Generated via /api/holo-walk/generate-splat** (operator-gated):
//      The route trains a splat from an uploaded video, uploads the
//      formats to Vercel Blob, and returns the asset bundle. Paste the
//      returned object verbatim into the location's `splat` field.
//
//   2. **External provider (Luma / Polycam / SuperSplat)**:
//      Train off-platform, upload the .ply (and optionally .spz / .ksplat
//      / .usdz) to Vercel Blob, and populate manually:
//        splat: {
//          plyUrl: "https://blob.vercel-storage.com/.../scene.ply",
//          spzUrl: "https://blob.vercel-storage.com/.../scene.spz",
//          gaussianCount: 250_000,
//          licence: "commercial-ok",
//          deployedAt: "2026-05-17T12:00:00Z",
//        }
//
//   3. **Marked splat-primary without an asset yet**:
//      Set `sculpture.kind = "splat"` AND give a `fallbackAttractor` —
//      the desktop preview + AR view will render the attractor until the
//      splat asset lands, then transparently swap. Useful when shooting
//      is scheduled but training isn't complete.
//
// The deploy capability (`viz.splat-ar-deploy`) enforces a commerce-safe
// licence — `research-only` outputs are rejected at the deploy boundary,
// so anything that lands in this catalogue is safe to ship to visitors.
// =============================================================================

